//! Clearance checking rule.
//!
//! Detects copper features that are too close together for manufacturing.
//! Uses the spatial index for efficient O(log n) candidate selection.

use cypcb_core::{Nm, Point};
use cypcb_world::BoardWorld;
use cypcb_world::components::NetId;
use hashbrown::{HashMap, HashSet};
use rstar::AABB;

use crate::presets::DesignRules;
use crate::violation::DrcViolation;

use super::DrcRule;

/// Rule for checking minimum clearance between copper features.
///
/// This rule verifies that all copper features on the same layer maintain
/// at least the minimum clearance distance specified by the design rules.
///
/// # Algorithm
///
/// 1. Iterate over all spatial entries
/// 2. For each entry, expand its bounding box by min_clearance
/// 3. Query the spatial index for overlapping candidates
/// 4. Filter candidates:
///    - Skip self
///    - Skip different layers (no copper overlap possible)
///    - Skip already-checked pairs (canonical ordering)
/// 5. Calculate actual AABB distance
/// 6. Report violations if distance < min_clearance
///
/// # Examples
///
/// ```rust,ignore
/// use cypcb_drc::rules::{ClearanceRule, DrcRule};
/// use cypcb_drc::presets::DesignRules;
/// use cypcb_world::BoardWorld;
///
/// let mut world = BoardWorld::new();
/// // ... populate world ...
///
/// let rules = DesignRules::jlcpcb_2layer();
/// let violations = ClearanceRule.check(&mut world, &rules);
///
/// for v in violations {
///     println!("Clearance violation at {:?}: {}", v.location, v.message);
/// }
/// ```
pub struct ClearanceRule;

impl DrcRule for ClearanceRule {
    fn name(&self) -> &'static str {
        "clearance"
    }

    fn check(&self, world: &mut BoardWorld, rules: &DesignRules) -> Vec<DrcViolation> {
        let mut violations = Vec::new();
        let min_clearance = rules.min_clearance;

        // Build entity -> NetId lookup for same-net exemption.
        // Entities on the same net (e.g. two pads both on VCC) should not
        // generate clearance violations — they're intentionally connected.
        let net_map: HashMap<u32, NetId> = {
            let ecs = world.ecs_mut();
            let mut query = ecs.query::<(bevy_ecs::entity::Entity, &NetId)>();
            query.iter(ecs).map(|(e, n)| (e.index(), *n)).collect()
        };

        // Track checked pairs to avoid A-B and B-A duplicates
        let mut checked_pairs: HashSet<(u32, u32)> = HashSet::new();

        // Collect all entries first to avoid borrowing issues
        let entries: Vec<_> = world.spatial().iter().cloned().collect();

        for entry in &entries {
            // Expand bounding box by min_clearance to find candidates
            let query_min = Point::new(
                Nm(entry.envelope.lower()[0] - min_clearance.0),
                Nm(entry.envelope.lower()[1] - min_clearance.0),
            );
            let query_max = Point::new(
                Nm(entry.envelope.upper()[0] + min_clearance.0),
                Nm(entry.envelope.upper()[1] + min_clearance.0),
            );

            // Phase 1: R*-tree query for candidates
            for candidate in world.spatial().query_region_entries(query_min, query_max) {
                // Skip self
                if candidate.entity == entry.entity {
                    continue;
                }

                // Skip if different layers (no copper overlap possible)
                if !entry.layers_overlap(candidate.layer_mask) {
                    continue;
                }

                // Canonical pair ordering to avoid duplicate checks
                let pair = canonical_pair(entry.entity.index(), candidate.entity.index());
                if !checked_pairs.insert(pair) {
                    continue; // Already checked
                }

                // Same-net exemption: skip clearance check if both entities
                // belong to the same net (they're electrically connected)
                if let (Some(net_a), Some(net_b)) = (
                    net_map.get(&entry.entity.index()),
                    net_map.get(&candidate.entity.index()),
                ) {
                    if net_a == net_b {
                        continue;
                    }
                }

                // Phase 2: Calculate actual distance between AABBs
                let distance = aabb_distance(&entry.envelope, &candidate.envelope);

                if distance < min_clearance.0 {
                    let location = aabb_center(&entry.envelope);
                    violations.push(DrcViolation::clearance(
                        entry.entity,
                        candidate.entity,
                        Nm(distance),
                        min_clearance,
                        location,
                    ));
                }
            }
        }

        violations
    }
}

/// Create a canonical pair ordering to avoid duplicate checks.
///
/// Always returns (smaller, larger) to ensure A-B and B-A map to the same key.
#[inline]
fn canonical_pair(a: u32, b: u32) -> (u32, u32) {
    if a < b {
        (a, b)
    } else {
        (b, a)
    }
}

/// Calculate the minimum distance between two axis-aligned bounding boxes.
///
/// Returns 0 if the AABBs touch or overlap.
/// Uses i128 intermediates to prevent overflow during distance calculation.
fn aabb_distance(a: &AABB<[i64; 2]>, b: &AABB<[i64; 2]>) -> i64 {
    // Calculate gap in each dimension
    // If boxes overlap in a dimension, the gap is 0
    let dx = (a.lower()[0].max(b.lower()[0]) - a.upper()[0].min(b.upper()[0])).max(0);
    let dy = (a.lower()[1].max(b.lower()[1]) - a.upper()[1].min(b.upper()[1])).max(0);

    // Euclidean distance using i128 to prevent overflow
    let dx_sq = (dx as i128) * (dx as i128);
    let dy_sq = (dy as i128) * (dy as i128);
    ((dx_sq + dy_sq) as f64).sqrt() as i64
}

/// Calculate the center point of an AABB.
fn aabb_center(aabb: &AABB<[i64; 2]>) -> Point {
    Point::new(
        Nm((aabb.lower()[0] + aabb.upper()[0]) / 2),
        Nm((aabb.lower()[1] + aabb.upper()[1]) / 2),
    )
}

#[cfg(test)]
mod tests {
    use super::*;
    use bevy_ecs::prelude::*;
    use cypcb_core::Point;
    use cypcb_world::SpatialEntry;
    use cypcb_world::components::NetId;

    use crate::ViolationKind;

    fn make_test_world_with_entries(entries: Vec<SpatialEntry>) -> BoardWorld {
        let mut world = BoardWorld::new();
        // Access the ECS world to directly populate the spatial index
        world.ecs_mut().resource_mut::<cypcb_world::SpatialIndex>().rebuild(entries);
        world
    }

    #[test]
    fn test_no_violation_when_far_apart() {
        // Two pads 10mm apart with 0.15mm clearance rule
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(10.0, 0.0),
                Point::from_mm(11.0, 1.0),
                0b01,
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer();
        let violations = ClearanceRule.check(&mut world, &rules);

        assert!(violations.is_empty(), "Should have no violations");
    }

    #[test]
    fn test_violation_when_too_close() {
        // Two pads 0.1mm apart with 0.15mm clearance rule
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(1.1, 0.0), // 0.1mm gap
                Point::from_mm(2.1, 1.0),
                0b01,
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer(); // 0.15mm clearance

        let violations = ClearanceRule.check(&mut world, &rules);

        assert_eq!(violations.len(), 1, "Should have one violation");
        assert_eq!(violations[0].kind, ViolationKind::Clearance);
    }

    #[test]
    fn test_no_violation_different_layers() {
        // Two pads overlapping but on different layers
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01, // Top only
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(0.5, 0.5), // Overlapping position
                Point::from_mm(1.5, 1.5),
                0b10, // Bottom only
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer();

        let violations = ClearanceRule.check(&mut world, &rules);

        assert!(
            violations.is_empty(),
            "Different layers should not cause violation"
        );
    }

    #[test]
    fn test_no_duplicate_violations() {
        // Ensure A-B violation is not reported twice as B-A
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(1.05, 0.0), // Very close (0.05mm gap)
                Point::from_mm(2.05, 1.0),
                0b01,
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer();

        let violations = ClearanceRule.check(&mut world, &rules);

        assert_eq!(violations.len(), 1, "Should only report once");
    }

    #[test]
    fn test_aabb_distance_no_overlap() {
        let a = AABB::from_corners([0, 0], [100, 100]);
        let b = AABB::from_corners([200, 0], [300, 100]);

        let dist = aabb_distance(&a, &b);
        assert_eq!(dist, 100, "Distance should be 100");
    }

    #[test]
    fn test_aabb_distance_touching() {
        let a = AABB::from_corners([0, 0], [100, 100]);
        let b = AABB::from_corners([100, 0], [200, 100]);

        let dist = aabb_distance(&a, &b);
        assert_eq!(dist, 0, "Touching AABBs have zero distance");
    }

    #[test]
    fn test_aabb_distance_overlapping() {
        let a = AABB::from_corners([0, 0], [100, 100]);
        let b = AABB::from_corners([50, 50], [150, 150]);

        let dist = aabb_distance(&a, &b);
        assert_eq!(dist, 0, "Overlapping AABBs have zero distance");
    }

    #[test]
    fn test_aabb_distance_diagonal() {
        // Two AABBs separated diagonally
        let a = AABB::from_corners([0, 0], [100, 100]);
        let b = AABB::from_corners([200, 200], [300, 300]);

        let dist = aabb_distance(&a, &b);
        // Diagonal distance: sqrt(100^2 + 100^2) = sqrt(20000) = ~141
        let expected = ((100_i64 * 100 + 100 * 100) as f64).sqrt() as i64;
        assert_eq!(dist, expected, "Diagonal distance calculation");
    }

    #[test]
    fn test_canonical_pair_ordering() {
        assert_eq!(canonical_pair(1, 2), (1, 2));
        assert_eq!(canonical_pair(2, 1), (1, 2));
        assert_eq!(canonical_pair(5, 5), (5, 5));
    }

    #[test]
    fn test_aabb_center() {
        let aabb = AABB::from_corners([0, 0], [1000, 2000]);
        let center = aabb_center(&aabb);
        assert_eq!(center.x, Nm(500));
        assert_eq!(center.y, Nm(1000));
    }

    #[test]
    fn test_same_net_exemption() {
        // Two pads very close together but on the same net — should NOT violate
        let mut world = BoardWorld::new();
        let vcc = NetId::new(42);

        // Spawn real entities in the ECS with NetId components
        let e0 = world.ecs_mut().spawn(vcc).id();
        let e1 = world.ecs_mut().spawn(vcc).id();

        let entries = vec![
            SpatialEntry::new(
                e0,
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                e1,
                Point::from_mm(1.05, 0.0), // 0.05mm gap — would fail 0.15mm clearance
                Point::from_mm(2.05, 1.0),
                0b01,
            ),
        ];

        world.ecs_mut().resource_mut::<cypcb_world::SpatialIndex>().rebuild(entries);

        let rules = DesignRules::jlcpcb_2layer();
        let violations = ClearanceRule.check(&mut world, &rules);

        assert!(violations.is_empty(), "Same-net pads should be exempt from clearance check");
    }

    #[test]
    fn test_different_net_still_violates() {
        // Two pads close together on DIFFERENT nets — should violate
        let mut world = BoardWorld::new();

        // Spawn real entities with different NetIds
        let e0 = world.ecs_mut().spawn(NetId::new(1)).id();
        let e1 = world.ecs_mut().spawn(NetId::new(2)).id();

        let entries = vec![
            SpatialEntry::new(
                e0,
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                e1,
                Point::from_mm(1.05, 0.0), // 0.05mm gap
                Point::from_mm(2.05, 1.0),
                0b01,
            ),
        ];

        world.ecs_mut().resource_mut::<cypcb_world::SpatialIndex>().rebuild(entries);

        let rules = DesignRules::jlcpcb_2layer();
        let violations = ClearanceRule.check(&mut world, &rules);

        assert_eq!(violations.len(), 1, "Different-net pads should still violate");
    }

    #[test]
    fn test_no_net_still_violates() {
        // Entities without NetId component — should still be checked (legacy behavior)
        let entries = vec![
            SpatialEntry::new(
                Entity::from_raw(0),
                Point::from_mm(0.0, 0.0),
                Point::from_mm(1.0, 1.0),
                0b01,
            ),
            SpatialEntry::new(
                Entity::from_raw(1),
                Point::from_mm(1.05, 0.0),
                Point::from_mm(2.05, 1.0),
                0b01,
            ),
        ];

        let mut world = make_test_world_with_entries(entries);
        let rules = DesignRules::jlcpcb_2layer();
        let violations = ClearanceRule.check(&mut world, &rules);

        assert_eq!(violations.len(), 1, "Entities without nets should still be checked");
    }
}

//! Unconnected pin detection rule (DRC-04).
//!
//! Validates that all component pins have net connections, catching
//! incomplete designs before manufacturing.

use cypcb_world::BoardWorld;
use cypcb_world::components::{FootprintRef, NetConnections, Position, RefDes};
use cypcb_world::footprint::FootprintLibrary;

use crate::presets::DesignRules;
use crate::violation::DrcViolation;
use super::DrcRule;

/// Rule that checks all component pins have net connections.
///
/// Iterates through all components with NetConnections, looks up their footprints,
/// and checks that each pin in the footprint has a corresponding net connection.
///
/// # Examples
///
/// ```rust,ignore
/// use cypcb_drc::rules::{UnconnectedPinRule, DrcRule};
/// use cypcb_drc::presets::DesignRules;
///
/// let rule = UnconnectedPinRule;
/// let mut world = BoardWorld::new();
/// // ... add components with incomplete nets ...
/// let rules = DesignRules::default();
/// let violations = rule.check(&mut world, &rules);
///

//! Minimum trace width rule (DRC-02).
//!
//! NOTE: This rule is a placeholder. Trace entities do not exist in the current
//! board model (Phase 1-3). When traces are added in Phase 5 (autorouting),
//! this rule will be implemented to check trace widths against min_trace_width.
//!
//! # Future Implementation
//!
//! When Phase 5 adds the Trace ECS component, this rule will:
//! 1. Query all Trace entities from the board world
//! 2. Check each trace's width against `rules.min_trace_width`
//! 3. Report violations with exact location on the trace segment
//!
//! # Design Rules Reference
//!
//! The `DesignRules.min_trace_width` field is already defined:
//! - JLCPCB 2-layer: 0.15mm (6 mil)
//! - JLCPCB 4-layer: 0.10mm (4 mil)
//! - PCBWay standard: 0.15mm
//! - Prototype: 0.25mm (10 mil)

//! DRC rule definitions and implementations.
//!
//! This module defines the [`DrcRule`] trait that all rules implement.
//! Design rules configuration is defined in the [`presets`](crate::presets) module.

pub mod annular_ring;
pub mod clearance;
pub mod connectivity;
pub mod drill_size;
pub mod edge_clearance;
pub mod trace_width;

use cypcb_world::BoardWorld;

use crate::presets::DesignRules;
use crate::violation::DrcViolation;

pub use annular_ring::AnnularRingRule;
pub use clearance::ClearanceRule;
pub use connectivity::UnconnectedPinRule;
pub use drill_size::MinDrillSizeRule;
pub use edge_clearance::EdgeClearanceRule;
pub use trace_width::MinTraceWidthRule;

/// A single DRC rule that can be executed against a board.
///
/// Rules are implemented as structs that hold no state. Configuration
/// comes from the [`DesignRules`] struct passed to `check()`.
///
/// # Object Safety
///
/// This trait is designed to be object-safe, allowing rules to be
/// stored in a `Vec<Box<dyn DrcRule>>` for flexible rule composition.
///
/// # Examples
///
/// ```rust,ignore
/// impl DrcRule for ClearanceRule {
///     fn name(&self) -> &'static str {
///         "clearance"
///     }
///
///     fn check(&self, world: &BoardWorld, rules: &DesignRules) -> Vec<DrcViolation> {
///         // Implementation...
///         vec![]
///     }
/// }
/// ```
pub trait DrcRule: Send + Sync {
    /// Rule identifier for error messages and filtering.
    fn name(&self) -> &'static str;

    /// Execute the rule check against the board world.
    ///
    /// Returns a list of violations (empty if rule passes).
    ///
    /// # Arguments
    ///
    /// * `world` - The board world to check (mutable for ECS queries)
    /// * `rules` - Design rules configuration
    ///
    /// Note: Takes `&mut BoardWorld` because bevy_ecs queries need to
    /// initialize their cache. No actual board data is modified.
    fn check(&self, world: &mut BoardWorld, rules: &DesignRules) -> Vec<DrcViolation>;
}

/// Rule for checking components against keepout zones.
///
/// This rule checks if any component's position falls within a keepout zone.
/// Note: Currently only checks center point - a more complete implementation
/// would check the entire component footprint bounds.
///
/// # Examples
///
/// ```rust,ignore
/// use cypcb_drc::rules::KeepoutRule;
/// use cypcb_drc::rules::DrcRule;
///
/// let rule = KeepoutRule;
/// let violations = rule.check(&world, &rules);
/// for v in violations {
///     println!("Keepout violation: {}", v.message);
/// }
/// ```
pub struct KeepoutRule;

impl DrcRule for KeepoutRule {
    fn name(&self) -> &'static str {
        "keepout"
    }

    fn check(&self, world: &mut BoardWorld, _rules: &DesignRules) -> Vec<DrcViolation> {
        let mut violations = Vec::new();

        // Collect all keepout zones
        let zones: Vec<_> = world.zones()
            .into_iter()
            .filter(|(_, zone)| zone.is_keepout())
            .collect();

        // If no keepout zones, skip
        if zones.is_empty() {
            return violations;
        }

        // Collect all components
        let components = world.components();

        // Check each component against keepout zones
        for (entity, refdes, position) in components {
            for (zone_entity, zone) in &zones {
                // Check if component center is inside zone
                if zone.contains(position.0) {
                    violations.push(DrcViolation::keepout(
                        entity,
                        *zone_entity,
                        refdes.as_str(),
                        zone.name.as_deref(),
                        position.0,
                    ));
                }
            }
        }

        violations
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use cypcb_core::{Point, Rect};
    use cypcb_world::components::{FootprintRef, NetConnections, Position, RefDes, Rotation, Value, Zone};
    use cypcb_world::components::zone::ZoneKind;
    use crate::ViolationKind;

    #[test]
    fn test_trait_object_safe() {
        // Verify that DrcRule can be used as a trait object
        fn _assert_object_safe(_: &dyn DrcRule) {}
    }

    #[test]
    fn test_rule_names() {
        assert_eq!(ClearanceRule.name(), "clearance");
        assert_eq!(MinDrillSizeRule.name(), "min-drill-size");
        assert_eq!(MinTraceWidthRule.name(), "min-trace-width");
        assert_eq!(UnconnectedPinRule.name(), "unconnected-pin");
        assert_eq!(KeepoutRule.name(), "keepout");
        assert_eq!(EdgeClearanceRule.name(), "edge-clearance");
        assert_eq!(AnnularRingRule.name(), "annular-ring");
    }

    #[test]
    fn test_rule_check_empty_world() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();

        // All rules should return empty on empty world
        assert!(ClearanceRule.check(&mut world, &rules).is_empty());
        assert!(MinDrillSizeRule.check(&mut world, &rules).is_empty());
        assert!(MinTraceWidthRule.check(&mut world, &rules).is_empty());
        assert!(UnconnectedPinRule.check(&mut world, &rules).is_empty());
        assert!(KeepoutRule.check(&mut world, &rules).is_empty());
        assert!(EdgeClearanceRule.check(&mut world, &rules).is_empty());
        assert!(AnnularRingRule.check(&mut world, &rules).is_empty());
    }

    #[test]
    fn test_rule_trait_object_vec() {
        // Verify rules can be collected into a Vec<Box<dyn DrcRule>>
        let rules: Vec<Box<dyn DrcRule>> = vec![
            Box::new(ClearanceRule),
            Box::new(MinDrillSizeRule),
            Box::new(MinTraceWidthRule),
            Box::new(UnconnectedPinRule),
            Box::new(KeepoutRule),
            Box::new(EdgeClearanceRule),
            Box::new(AnnularRingRule),
        ];
        assert_eq!(rules.len(), 7);
        assert_eq!(rules[0].name(), "clearance");
        assert_eq!(rules[1].name(), "min-drill-size");
        assert_eq!(rules[2].name(), "min-trace-width");
        assert_eq!(rules[3].name(), "unconnected-pin");
        assert_eq!(rules[4].name(), "keepout");
        assert_eq!(rules[5].name(), "edge-clearance");
        assert_eq!(rules[6].name(), "annular-ring");
    }

    #[test]
    fn test_keepout_rule_detects_violation() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();

        // Create a keepout zone
        let zone = Zone {
            bounds: Rect::new(
                Point::from_mm(10.0, 10.0),
                Point::from_mm(20.0, 20.0),
            ),
            kind: ZoneKind::Keepout,
            layer_mask: 0xFFFFFFFF,
            name: Some("test_zone".to_string()),
        };
        world.ecs_mut().spawn(zone);

        // Create a component inside the zone
        world.spawn_component(
            RefDes::new("R1"),
            Value::new("10k"),
            Position::from_mm(15.0, 15.0), // Inside zone
            Rotation::ZERO,
            FootprintRef::new("0402"),
            NetConnections::new(),
        );

        // Run the rule
        let violations = KeepoutRule.check(&mut world, &rules);
        assert_eq!(violations.len(), 1, "expected 1 violation");
        assert_eq!(violations[0].kind, ViolationKind::KeepoutViolation);
        assert!(violations[0].message.contains("R1"));
        assert!(violations[0].message.contains("test_zone"));
    }

    #[test]
    fn test_keepout_rule_no_violation_outside() {
        let mut world = BoardWorld::new();
        let rules = DesignRules::default();

        // Create a keepout zone
        let zone = Zone {
            bounds: Rect::new(
